// Tezz Language — TypeScript Declaration Generator (.d.ts)

function mapType(t) {
  if (!t) return "any";
  const clean = t.trim().toLowerCase();
  if (["int", "float", "number"].includes(clean)) return "number";
  if (["string", "str"].includes(clean)) return "string";
  if (["bool", "boolean"].includes(clean)) return "boolean";
  if (clean === "void") return "void";
  if (clean.endsWith("[]")) return `${mapType(clean.slice(0, -2))}[]`;
  return t; // Custom class or interface name
}

function generateDts(ast) {
  const lines = [
    "// Generated by Tezz (तेज़) Compiler v0.5.0",
    "// TypeScript Type Definitions (.d.ts)",
    ""
  ];

  for (const node of ast.body) {
    switch (node.type) {
      case "FunctionDeclaration": {
        const params = (node.params || []).map(p => `${p.name}: ${mapType((p.paramType || p.typeAnn))}`).join(", ");
        const retType = mapType(node.returnType);
        lines.push(`export declare function ${node.name}(${params}): ${retType};`);
        break;
      }
      case "ClassDeclaration": {
        const ext = node.superclass ? ` extends ${node.superclass}` : "";
        const impl = (node.implements && node.implements.length > 0) ? ` implements ${node.implements.join(", ")}` : "";
        lines.push(`export declare class ${node.name}${ext}${impl} {`);
        for (const m of node.methods || []) {
          const params = (m.params || []).map(p => {
            const name = typeof p === "object" ? p.name : p;
            const ann = typeof p === "object" ? (p.paramType || p.typeAnn) : null;
            return `${name}: ${mapType(ann)}`;
          }).join(", ");
          const retType = mapType(m.returnType);
          lines.push(`  ${m.name}(${params}): ${retType};`);
        }
        lines.push("}");
        break;
      }
      case "TraitDeclaration": {
        lines.push(`export interface ${node.name} {`);
        for (const m of node.methods || []) {
          const params = (m.params || []).map(p => `${p.name}: ${mapType((p.paramType || p.typeAnn))}`).join(", ");
          const retType = mapType(m.returnType);
          lines.push(`  ${m.name}(${params}): ${retType};`);
        }
        lines.push("}");
        break;
      }
      case "ServiceDeclaration": {
        lines.push(`export declare const ${node.name}: {`);
        lines.push("  listen(port?: number, cb?: () => void): any;");
        lines.push("};");
        break;
      }
      case "VariableDeclaration": {
        if (typeof node.name === "string" && /^[a-zA-Z_]\w*$/.test(node.name)) {
          const kind = node.kind === "const" ? "const" : "let";
          lines.push(`export declare ${kind} ${node.name}: ${mapType(node.typeAnn)};`);
        }
        break;
      }
    }
  }

  return lines.join("\n") + "\n";
}

module.exports = { generateDts, mapType };
